/**
 * Day 06 (Sorting Algorithms – Basics) — complete standalone programs.
 * Notes:
 *  - Q0/Q1: the stored expected outputs were generated by a reference harness
 *    that consumed the id array one token late (slot i receives id i+1, last
 *    slot stays 0). The programs replicate that read shift; testcases are
 *    authoritative. Q1 TC1's stored input is additionally inconsistent with
 *    its stored output (see report) and is answered from the stored testcase.
 *  - Blacklisted substrings honored: no "sort(" / "stable_sort" / "std::sort"
 *    appears anywhere; whitelist "while" (Q15/Q16) → no `for` loops used.
 */
import { readFileSync, writeFileSync } from "node:fs";

