const src = JSON.parse(readFileSync(SRC, "utf8"));
if (src.questions.length !== programs.length)
  throw new Error(`expected ${src.questions.length} programs, have ${programs.length}`);
src.questions.forEach((q, i) => {
  q.sourcecode = programs[i];
});
writeFileSync(OUT, JSON.stringify(src, null, 2));
console.log(`day-06.code.json written: ${src.questions.length} questions`);
